/**
 * Which exercises have a licensed demo (start + end frame) on Cloudinary at
 * `repwise/exercises/<id>` and `repwise/exercises/<id>-end`.
 *
 * media/exercises-with-media.json is generated by scripts/media/build-exercise-media-map.mjs from
 * the reviewed matches; sources, licence and confidence per exercise live in
 * media/exercise-media-map.json (docs/MEDIA_STATUS.md). The app requests media only for these ids,
 * so the exercises without a licensed demo show the offline placeholder and never trigger a 404.
 */
import list from '../media/exercises-with-media.json';

const ids: ReadonlySet<string> = new Set(list.exercises as string[]);

/** Ids of exercises with a licensed start + end frame. */
export const EXERCISES_WITH_MEDIA: ReadonlySet<string> = ids;

/** True when the exercise has a licensed demo (`repwise/exercises/<id>` and `<id>-end`). */
export function exerciseHasMedia(exerciseId: string): boolean {
  return ids.has(exerciseId);
}
